func (r *StatusPageResource) Update(ctx context.Context, req resource.UpdateRequest, resp *resource.UpdateResponse) {
	defer rememberConfigured(ctx, req.Config, resp.Private, statusPageKeptOnRemoval, &resp.Diagnostics)
	var plan StatusPageModel
	resp.Diagnostics.Append(req.Plan.Get(ctx, &plan)...)
	var request StatusPageModel
	resp.Diagnostics.Append(configWithPlannedUnknowns(ctx, req.Config, req.Plan, req.State.Raw, &request)...)
	request.Sections = withPlannedIDs(ctx, request.Sections, plan.Sections, itemMatch{Keys: [][]string{{"name"}}, Children: map[string]itemMatch{"resources": itemMatch{Keys: [][]string{{"resource_type", "resource_id"}, {"resource_type", "public_name"}}}}}, &resp.Diagnostics)
	var state StatusPageModel
	resp.Diagnostics.Append(req.State.Get(ctx, &state)...)
	if resp.Diagnostics.HasError() {
		return
	}
	// An unset line's default travels only when it changes the stored value (the line was just
	// removed): resending an unchanged default can act on its own, e.g. unpause a group's members.
	if !plan.AnnouncementEmbedVisible.Equal(state.AnnouncementEmbedVisible) {
		request.AnnouncementEmbedVisible = plan.AnnouncementEmbedVisible
	}
	if !plan.AutomaticReports.Equal(state.AutomaticReports) {
		request.AutomaticReports = plan.AutomaticReports
	}
	if !plan.Design.Equal(state.Design) {
		request.Design = plan.Design
	}
	if !plan.HideFromSearchEngines.Equal(state.HideFromSearchEngines) {
		request.HideFromSearchEngines = plan.HideFromSearchEngines
	}
	if !plan.History.Equal(state.History) {
		request.History = plan.History
	}
	if !plan.Layout.Equal(state.Layout) {
		request.Layout = plan.Layout
	}
	if !plan.MinIncidentLength.Equal(state.MinIncidentLength) {
		request.MinIncidentLength = plan.MinIncidentLength
	}
	if !plan.PasswordEnabled.Equal(state.PasswordEnabled) {
		request.PasswordEnabled = plan.PasswordEnabled
	}
	if !plan.Published.Equal(state.Published) {
		request.Published = plan.Published
	}
	if !plan.RequireSso.Equal(state.RequireSso) {
		request.RequireSso = plan.RequireSso
	}
	if !plan.Subscribable.Equal(state.Subscribable) {
		request.Subscribable = plan.Subscribable
	}
	if !plan.Theme.Equal(state.Theme) {
		request.Theme = plan.Theme
	}
	if !plan.Whitelabeled.Equal(state.Whitelabeled) {
		request.Whitelabeled = plan.Whitelabeled
	}
	vars := map[string]string{}
	vars["id"] = plan.Id.ValueString()
	out, err := r.client.Update(ctx, statusPageBinding, vars, r.updateBody(ctx, request, plan, state))
	if err != nil {
		addAPIError(&resp.Diagnostics, "updating status_page", err, req.Plan.Raw.Type())
		return
	}
	if out == nil {
		out = map[string]interface{}{}
	}
	r.mergeResponse(ctx, state, out)
	resp.State.Raw = stateFromPlan(req.Plan.Raw, req.State.Raw, out)
}

